  /// Operational trust assessment, maintained by the compliance team.\n  verifiedTier VerifiedTier @default(unverified)\n  riskFlags    String[]     @default([])\n  notes        String?\n\n  assets Asset[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([verifiedTier])\n}\n\nmodel Asset {\n  id String @id @default(cuid())\n\n  /// Derived identity: `${chainId}:${contract|lower|native}:${issuerId}`.\n  /// Enforced in application code by `deriveAssetId()`.\n  assetId String @unique\n\n  chainId         String\n  chain           Chain         @relation(fields: [chainId], references: [id])\n  contractAddress String?\n  tokenStandard   TokenStandard @default(erc20)\n  symbol          String\n  name            String\n  decimals        Int\n  category        AssetCategory\n\n  issuerId String\n  issuer   Issuer @relation(fields: [issuerId], references: [id])\n\n  // --- Backing: the provenance payload. This is the product. ---\n  custodyModel       CustodyModel       @default(synthetic)\n  custodian          String?\n  vaultLocations     String[]           @default([])\n  proofOfReserveUrl  String?\n  attestationCadence AttestationCadence @default(none)\n  lastAttestedAt     DateTime?\n  gramsPerToken      Decimal?           @db.Decimal(18, 6)\n  ouncesPerToken     Decimal?           @db.Decimal(18, 8)\n\n  // --- Trading ---\n  transferSupported Boolean    @default(true)\n  swapSupported     Boolean    @default(false)\n  redeemSupported   Boolean    @default(false)\n  rails             RailKind[] @default([])\n\n  // --- Trust ---\n  verifiedTier VerifiedTier @default(unverified)\n  riskFlags    String[]     @default([])\n\n  // --- Display ---\n  iconUrl     String?\n  accentColor String?\n\n  enabled Boolean @default(true)\n\n  accounts     WalletAccount[]\n  quotesAsFrom SwapQuote[]         @relation(\"QuoteFromAsset\")\n  quotesAsTo   SwapQuote[]         @relation(\"QuoteToAsset\")\n  transactions Transaction[]\n  prices       